"use client";

import React, { useState, useMemo } from "react";
import {
    Briefcase,
    MapPin,
    Linkedin,
    Mail,
    Award,
    Search,
    BookOpen,
    Building2,
    Users
} from "lucide-react";
import { foundingMembers, FoundingMember } from "@/data/foundingMembers";
import { RevealOnScroll } from "@/hooks/useScrollReveal";

// Types pour les filtres et la pagination
type FilterType = 'all' | 'founders' | 'board';

const FoundingMembersSection: React.FC = () => {
    const [activeFilter, setActiveFilter] = useState<FilterType>("all");
    const [searchQuery, setSearchQuery] = useState("");
    const [visibleCount, setVisibleCount] = useState(8);

    // Filtrage des membres
    const filteredMembers = useMemo(() => {
        return foundingMembers.filter((member) => {
            const matchesSearch =
                member.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
                member.company.toLowerCase().includes(searchQuery.toLowerCase()) ||
                member.position.toLowerCase().includes(searchQuery.toLowerCase());

            if (activeFilter === "all") return matchesSearch;
            if (activeFilter === "board")
                return (
                    matchesSearch &&
                    (member.status.includes("Président") ||
                        member.status.includes("Vice") ||
                        member.status.includes("Secrétaire") ||
                        member.status.includes("Trésorier"))
                );
            if (activeFilter === "founders")
                return matchesSearch && member.status.includes("Membre fondateur");

            return matchesSearch;
        });
    }, [activeFilter, searchQuery]);

    // Membres visibles selon la pagination
    const visibleMembers = filteredMembers.slice(0, visibleCount);
    const hasMore = visibleCount < filteredMembers.length;

    const handleLoadMore = () => {
        setVisibleCount((prev) => prev + 8);
    };

    return (
        <section id="membres" className="py-20 bg-gray-50 relative overflow-hidden">
            {/* Arrière-plan décoratif */}
            <div className="absolute inset-0 pointer-events-none">
                <div className="absolute top-0 right-0 w-1/3 h-full bg-gradient-to-l from-primary-light/5 to-transparent"></div>
                <div className="absolute bottom-0 left-0 w-1/3 h-1/3 bg-gradient-to-tr from-primary-light/5 to-transparent rounded-full"></div>
            </div>

            <div className="container mx-auto px-4 md:px-8 relative z-10">
                <RevealOnScroll animation="fadeInUp">
                    <div className="text-center mb-12">
                        <h2 className="text-3xl md:text-4xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-primary to-primary-dark mb-4">
                            Membres Fondateurs
                        </h2>
                        <div className="h-1.5 w-24 bg-gradient-to-r from-primary-light to-primary mx-auto rounded-full mb-6"></div>
                        <p className="text-xl text-gray-600 max-w-2xl mx-auto">
                            Une équipe d'experts passionnés unis pour propulser le numérique en Algérie
                        </p>
                    </div>
                </RevealOnScroll>

                {/* C - Barre de filtres et recherche */}
                <div className="mb-12 space-y-4 md:space-y-0 md:flex md:items-center md:justify-between bg-white p-4 rounded-xl shadow-md border border-gray-100">
                    <div className="flex flex-wrap gap-2">
                        <button
                            onClick={() => setActiveFilter("all")}
                            className={`px-4 py-2 rounded-lg text-sm font-medium transition-all duration-300 ${activeFilter === "all"
                                    ? "bg-primary text-white shadow-lg shadow-primary/30"
                                    : "bg-gray-100 text-gray-600 hover:bg-gray-200"
                                }`}
                        >
                            Tous les membres
                        </button>
                        <button
                            onClick={() => setActiveFilter("board")}
                            className={`px-4 py-2 rounded-lg text-sm font-medium transition-all duration-300 ${activeFilter === "board"
                                    ? "bg-primary text-white shadow-lg shadow-primary/30"
                                    : "bg-gray-100 text-gray-600 hover:bg-gray-200"
                                }`}
                        >
                            Bureau Exécutif
                        </button>
                        <button
                            onClick={() => setActiveFilter("founders")}
                            className={`px-4 py-2 rounded-lg text-sm font-medium transition-all duration-300 ${activeFilter === "founders"
                                    ? "bg-primary text-white shadow-lg shadow-primary/30"
                                    : "bg-gray-100 text-gray-600 hover:bg-gray-200"
                                }`}
                        >
                            Membres Fondateurs
                        </button>
                    </div>

                    <div className="relative w-full md:w-auto md:min-w-[300px]">
                        <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-4 h-4" />
                        <input
                            type="text"
                            placeholder="Rechercher un membre, une expertise..."
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                            className="w-full pl-10 pr-4 py-2 rounded-lg border border-gray-200 focus:border-primary focus:ring-2 focus:ring-primary/20 outline-none transition-all"
                        />
                    </div>
                </div>

                {/* Grille des membres */}
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                    {visibleMembers.map((member: FoundingMember, index) => (
                        <RevealOnScroll key={member.id} animation="fadeInUp" delay={index * 0.05} duration={0.5}>
                            <div className="group h-full bg-white rounded-2xl p-6 shadow-sm hover:shadow-xl transition-all duration-300 border border-gray-100 hover:border-primary-light/30 flex flex-col relative overflow-hidden">
                                {/* Effet de survol background */}
                                <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-primary-light to-primary transform origin-left scale-x-0 group-hover:scale-x-100 transition-transform duration-300"></div>

                                {/* En-tête avec Avatar et LinkedIn */}
                                <div className="flex items-start justify-between mb-4">
                                    <div className="relative">
                                        <div className="w-16 h-16 rounded-full bg-gradient-to-br from-gray-100 to-gray-200 flex items-center justify-center border-2 border-white shadow-md group-hover:border-primary-light/50 transition-colors">
                                            {member.photo ? (
                                                <img
                                                    src={member.photo}
                                                    alt={member.name}
                                                    className="w-full h-full rounded-full object-cover"
                                                />
                                            ) : (
                                                <span className="text-xl font-bold text-gray-400 group-hover:text-primary transition-colors">
                                                    {member.name.charAt(0)}
                                                </span>
                                            )}
                                        </div>
                                        <div className="absolute -bottom-1 -right-1 bg-white rounded-full p-1 shadow-sm">
                                            <div className="w-4 h-4 rounded-full bg-green-500 border-2 border-white"></div>
                                        </div>
                                    </div>
                                    <a
                                        href={member.linkedin}
                                        target="_blank"
                                        rel="noopener noreferrer"
                                        className="p-2 bg-blue-50 text-blue-600 rounded-full hover:bg-blue-600 hover:text-white transition-all duration-300 group-hover:scale-110"
                                        aria-label={`LinkedIn de ${member.name}`}
                                    >
                                        <Linkedin className="w-4 h-4" />
                                    </a>
                                </div>

                                {/* Informations Principales */}
                                <div className="mb-4">
                                    <h3 className="text-lg font-bold text-gray-900 mb-1 group-hover:text-primary transition-colors line-clamp-1" title={member.name}>
                                        {member.name}
                                    </h3>
                                    <div className="flex items-center text-primary font-medium text-xs mb-2 bg-primary/5 py-1 px-2 rounded-md w-fit">
                                        <Award className="w-3 h-3 mr-1" />
                                        {member.status}
                                    </div>
                                </div>

                                {/* Détails Professionnels */}
                                <div className="space-y-3 mb-6 flex-grow">
                                    <div className="flex items-start text-sm text-gray-600">
                                        <Briefcase className="w-4 h-4 mr-2 mt-0.5 text-gray-400 flex-shrink-0" />
                                        <span className="line-clamp-2">{member.position}</span>
                                    </div>
                                    <div className="flex items-center text-sm text-gray-600">
                                        <Building2 className="w-4 h-4 mr-2 text-gray-400 flex-shrink-0" />
                                        <span className="font-medium truncate">{member.company}</span>
                                    </div>
                                    <div className="flex items-center text-sm text-gray-600">
                                        <Mail className="w-4 h-4 mr-2 text-gray-400 flex-shrink-0" />
                                        <a href={`mailto:${member.email}`} className="hover:text-primary truncate transition-colors">
                                            {member.email}
                                        </a>
                                    </div>
                                </div>

                                {/* Expertises (limitées à 2 pour l'affichage) */}
                                <div className="pt-4 border-t border-gray-100 mt-auto">
                                    <div className="flex flex-wrap gap-2">
                                        {member.specialties.slice(0, 2).map((specialty: string, i: number) => (
                                            <span
                                                key={i}
                                                className="px-2 py-1 bg-gray-50 text-gray-600 text-xs rounded-md border border-gray-100"
                                            >
                                                {specialty}
                                            </span>
                                        ))}
                                        {member.specialties.length > 2 && (
                                            <span className="px-2 py-1 bg-gray-50 text-gray-400 text-xs rounded-md border border-gray-100">
                                                +{member.specialties.length - 2}
                                            </span>
                                        )}
                                    </div>
                                </div>
                            </div>
                        </RevealOnScroll>
                    ))}
                </div>

                {/* Bouton Voir Plus */}
                {hasMore && (
                    <RevealOnScroll animation="fadeInUp" delay={0.2}>
                        <div className="text-center mt-12">
                            <button
                                onClick={handleLoadMore}
                                className="group px-8 py-3 bg-white text-primary border border-primary-light/30 rounded-full font-semibold hover:bg-primary hover:text-white transition-all duration-300 hover:shadow-lg hover:shadow-primary/20 flex items-center justify-center mx-auto"
                            >
                                <span>Voir plus de membres</span>
                                <Users className="w-4 h-4 ml-2 group-hover:scale-110 transition-transform" />
                            </button>
                        </div>
                    </RevealOnScroll>
                )}
            </div>
        </section>
    );
};

export default FoundingMembersSection;
